      if(toolsListEl){
        toolsListEl.innerHTML = tools.length ? tools.map(t=>'<div class="mcp-tool-row"><div class="mcp-tool-exposed">'+esc(t.exposedName)+'</div><div class="mcp-tool-raw">server tool: '+esc(t.toolName)+'</div>'+(t.description?'<div class="mcp-tool-desc">'+esc(t.description)+'</div>':'')+'</div>').join('')
          : '<div class="mcp-tools-empty">No tools reported by this server.</div>';
      }
